CREATE TABLE asset_imports (id TEXT PRIMARY KEY NOT NULL, project_id TEXT NOT NULL, owner_id TEXT NOT NULL, operation_id TEXT NOT NULL, request_hash TEXT NOT NULL, request_json TEXT NOT NULL CHECK(json_valid(request_json)), state TEXT NOT NULL CHECK(state IN('PENDING','UPLOADED','VERIFIED')), inspection_json TEXT CHECK(inspection_json IS NULL OR json_valid(inspection_json)), object_key TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(owner_id,operation_id), FOREIGN KEY(project_id,owner_id) REFERENCES projects(id,owner_id) ON DELETE RESTRICT);
